'use client';
import { useEffect, useMemo, useState } from 'react';
import Link from 'next/link';
import { collection, deleteDoc, doc, getDoc, getDocs, orderBy, query, serverTimestamp, setDoc, Timestamp, updateDoc } from 'firebase/firestore';
import { db } from '@/lib/firebase';
import { PageShell } from '@/components/PageShell';
import { Protected } from '@/components/Protected';
import { uploadAdminAsset } from '@/lib/storage';
import type { Channel, MediaItem, UserProfile, Category, PlayerType, AdBanner, AccessLevel, DramaEpisode, FilmPart, AdAudience, AdPlacement } from '@/lib/types';
import { Edit3, Film, Plus, Radio, Save, ShieldCheck, Trash2, X, Megaphone, Clapperboard, Crown, Upload, Image as ImageIcon, MonitorPlay, LayoutTemplate, MousePointerClick, Layers } from 'lucide-react';
import { useApp } from '@/components/AppProvider';

const categories: Category[] = ['NEWS','SPORTS','BEIN','MOVIES','KIDS','KURDISH','ENTERTAINMENT'];
const isHttpUrl = (value: string) => { try { const u = new URL(value); return u.protocol === 'http:' || u.protocol === 'https:'; } catch { return false; } };
const toDateMillis = (value: unknown): number | null => {
  if (!value) return null;
  if (value instanceof Date) return value.getTime();
  if (typeof value === 'string' || typeof value === 'number') {
    const time = new Date(value).getTime();
    return Number.isFinite(time) ? time : null;
  }
  if (typeof value === 'object' && value !== null && 'toMillis' in value) {
    const millis = (value as { toMillis?: () => number }).toMillis?.();
    return typeof millis === 'number' ? millis : null;
  }
  return null;
};
const stripUndefined = (value: any): any => {
  if (Array.isArray(value)) return value.map(stripUndefined);
  if (value && typeof value === 'object' && !(value instanceof Date) && typeof value.toMillis !== 'function') {
    return Object.fromEntries(Object.entries(value).filter(([,v]) => v !== undefined).map(([k,v]) => [k, stripUndefined(v)]));
  }
  return value;
};const emptyChannel: Channel = { id:'', name:'', category:'NEWS', description:'', logo:'', streamUrl:'', playerType:'video', enabled:false, accessLevel:'free' };
const emptyMedia: MediaItem = { id:'', title:'', type:'film', year:new Date().getFullYear(), genre:'', description:'', poster:'', streamUrl:'', playerType:'video', enabled:false, accessLevel:'free' };
const emptyEpisode: DramaEpisode = { id:'', dramaId:'', title:'', seasonNumber:1, episodeNumber:1, durationMinutes:45, description:'', thumbnail:'', streamUrl:'', playerType:'video', enabled:false, accessLevel:'free' };
const emptyPart: FilmPart = { id:'', mediaId:'', partNumber:1, title:'', durationMinutes:0, description:'', streamUrl:'', playerType:'video', enabled:false, accessLevel:'free' };
const emptyAd: AdBanner = { id:'', title:'', image:'', mobileImage:'', link:'', placement:'banner', audience:'all', enabled:true, order:1, priority:0, startAt:'', endAt:'', frequencySeconds:20, skipAfterSeconds:5 };

export default function Admin(){
 const {user}=useApp(); const [allowed,setAllowed]=useState(false); const [users,setUsers]=useState<UserProfile[]>([]); const [auditLogs,setAuditLogs]=useState<any[]>([]); const [userFilter,setUserFilter]=useState<'all'|'vip'|'free'>('all'); const [channels,setChannels]=useState<Channel[]>([]); const [media,setMedia]=useState<MediaItem[]>([]); const [episodes,setEpisodes]=useState<DramaEpisode[]>([]); const [parts,setParts]=useState<FilmPart[]>([]); const [ads,setAds]=useState<AdBanner[]>([]); const [tab,setTab]=useState<'dashboard'|'users'|'channels'|'media'|'episodes'|'parts'|'ads'|'audit'>('dashboard'); const [channelForm,setChannelForm]=useState({...emptyChannel}); const [mediaForm,setMediaForm]=useState({...emptyMedia}); const [episodeForm,setEpisodeForm]=useState({...emptyEpisode}); const [partForm,setPartForm]=useState({...emptyPart}); const [adForm,setAdForm]=useState({...emptyAd}); const [editingChannel,setEditingChannel]=useState<string|null>(null); const [editingMedia,setEditingMedia]=useState<string|null>(null); const [editingEpisode,setEditingEpisode]=useState<string|null>(null); const [editingPart,setEditingPart]=useState<string|null>(null); const [editingAd,setEditingAd]=useState<string|null>(null); const [busy,setBusy]=useState(''); const [message,setMessage]=useState('');
 const load=async()=>{if(!user)return;setBusy('load');try{const [us,cs,ms,es,ps,as,al]=await Promise.all([getDocs(query(collection(db,'users'),orderBy('createdAt','desc'))).catch(()=>getDocs(collection(db,'users'))),getDocs(collection(db,'channels')),getDocs(collection(db,'media')),getDocs(collection(db,'episodes')),getDocs(collection(db,'parts')).catch(()=>({docs:[]} as any)),getDocs(collection(db,'ads')),getDocs(collection(db,'auditLogs')).catch(()=>({docs:[]} as any))]);setUsers(us.docs.map(d=>d.data() as UserProfile));setChannels(cs.docs.map(d=>({id:d.id,...d.data()} as Channel)).map(x=>({...x,accessLevel:x.accessLevel||'free'})));setMedia(ms.docs.map(d=>({id:d.id,...d.data()} as MediaItem)).map(x=>({...x,accessLevel:x.accessLevel||'free'})));setEpisodes(es.docs.map(d=>({id:d.id,...d.data()} as DramaEpisode)).map(x=>({...x,accessLevel:x.accessLevel||'free'})));setParts(ps.docs.map((d:any)=>({id:d.id,...d.data()} as FilmPart)).map((x:any)=>({...x,accessLevel:x.accessLevel||'free'})));setAds(as.docs.map(d=>({id:d.id,...d.data()} as AdBanner)).sort((a,b)=>(a.order??0)-(b.order??0)));setAuditLogs(al.docs.map((d:any)=>({id:d.id,...d.data()})).sort((a:any,b:any)=>(toDateMillis(b.createdAt)||0)-(toDateMillis(a.createdAt)||0)).slice(0,100));}finally{setBusy('');}};
 useEffect(()=>{if(user)getDoc(doc(db,'admins',user.uid)).then(s=>setAllowed(s.exists()&&s.data()?.active===true));},[user]); useEffect(()=>{if(allowed)load();},[allowed]);
 const writeAudit=async(action:string,target:string,details?:any)=>{try{await setDoc(doc(collection(db,'auditLogs')),stripUndefined({adminUid:user?.uid,action,target,details:details||null,createdAt:serverTimestamp()}));}catch{}};
 const save=async(type:'channel'|'media'|'episode'|'part'|'ad')=>{
  const form=type==='channel'?channelForm:type==='media'?mediaForm:type==='episode'?episodeForm:type==='part'?partForm:adForm;
  const title=type==='channel'?(form as Channel).name:type==='media'?(form as MediaItem).title:type==='episode'?(form as DramaEpisode).title:type==='part'?((form as FilmPart).title||`Part ${(form as FilmPart).partNumber||1}`):(form as AdBanner).title;
  if(type!=='part'&&!title?.trim()){setMessage('Title / name is required.');return false;}
  if(type==='episode'&&!episodeForm.dramaId){setMessage('Choose a drama first.');return false;}
  if(type==='part'&&!partForm.mediaId){setMessage('Choose a film first.');return false;}
  if(type==='ad'&&!adForm.image){setMessage('Advertisement image is required.');return false;}
  if(type==='channel'&&!channelForm.streamUrl){setMessage('Stream URL is required.');return false;}
  const urls:string[]=[];
  if(type==='channel'&&channelForm.streamUrl) urls.push(channelForm.streamUrl);
  if(type==='media'){urls.push(...[mediaForm.streamUrl,mediaForm.trailerUrl,mediaForm.backdrop,mediaForm.poster,mediaForm.logo].filter(Boolean) as string[]); urls.push(...(mediaForm.images||[]).map((x:any)=>x.url).filter(Boolean)); urls.push(...(mediaForm.servers||[]).map((x:any)=>x.url).filter(Boolean)); urls.push(...(mediaForm.subtitles||[]).map((x:any)=>x.src).filter(Boolean));}
  if(type==='episode'){urls.push(...[episodeForm.streamUrl,episodeForm.thumbnail].filter(Boolean) as string[]); urls.push(...(episodeForm.servers||[]).map((x:any)=>x.url).filter(Boolean)); urls.push(...(episodeForm.subtitles||[]).map((x:any)=>x.src).filter(Boolean));}
  if(type==='part'){urls.push(...[partForm.streamUrl].filter(Boolean) as string[]); urls.push(...(partForm.servers||[]).map((x:any)=>x.url).filter(Boolean)); urls.push(...(partForm.subtitles||[]).map((x:any)=>x.src).filter(Boolean));}
  if(type==='ad'&&adForm.link) urls.push(adForm.link);
  if(urls.some((url)=>!isHttpUrl(url))){setMessage('One or more URLs are invalid. Use http:// or https:// links.');return false;}
  if(type==='media' && mediaForm.rating != null && (Number(mediaForm.rating)<0 || Number(mediaForm.rating)>10)){setMessage('Rating must be between 0 and 10.');return false;}
  if(type==='ad'){const start=toDateMillis(adForm.startAt);const end=toDateMillis(adForm.endAt);if(start!==null&&end!==null&&end<start){setMessage('End date must be after the start date.');return false;}}
  const rawId=String((form as any).id||'').trim();
  const generatedId=type==='episode'?`${episodeForm.dramaId}-s${episodeForm.seasonNumber}-e${episodeForm.episodeNumber}`:type==='part'?`${partForm.mediaId}-part-${partForm.partNumber}`:`${title||type}`.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||`${type}-${Date.now().toString(36)}`;
  const id=rawId||generatedId;
  const collectionName=type==='channel'?'channels':type==='media'?'media':type==='episode'?'episodes':type==='part'?'parts':'ads';
  setBusy(type);
  try{
    const ref=doc(db,collectionName,id);
    const existing=await getDoc(ref);
    const payload=stripUndefined({...form,id,title,accessLevel:(form as any).accessLevel||'free',updatedAt:serverTimestamp()});
    if(!existing.exists()) payload.createdAt=serverTimestamp();
    await setDoc(ref,payload,{merge:true});
    setMessage('Saved successfully.');
    await writeAudit(existing.exists()?'update':'create',`${collectionName}/${id}`,{type,title});
    clear(type);
    await load();
    return true;
  }catch(e:any){
    const message=e?.message||'Save failed.';
    setMessage(message);
    throw e;
  }finally{setBusy('');}
 };
 const clear=(type:string,keep?:Partial<any>)=>{if(type==='channel'){setEditingChannel(null);setChannelForm({...emptyChannel,...keep})}if(type==='media'){setEditingMedia(null);setMediaForm({...emptyMedia,...keep})}if(type==='episode'){setEditingEpisode(null);setEpisodeForm({...emptyEpisode,...keep})}if(type==='part'){setEditingPart(null);setPartForm({...emptyPart,...keep})}if(type==='ad'){setEditingAd(null);setAdForm({...emptyAd,...keep})}};
 const remove=async(type:'channels'|'media'|'episodes'|'parts'|'ads',id:string)=>{if(!confirm('Delete this item?'))return;setBusy(id);try{await deleteDoc(doc(db,type,id));await writeAudit('delete',`${type}/${id}`);await load();}finally{setBusy('')}};
 const setVip=async(u:UserProfile,days:number|null)=>{setBusy(`vip-${u.uid}`);try{if(days===null)await updateDoc(doc(db,'users',u.uid),{plan:'free',vipUntil:null});else await updateDoc(doc(db,'users',u.uid),{plan:'vip',vipUntil:Timestamp.fromDate(new Date(Date.now()+days*86400000))});await writeAudit('vip-change',`users/${u.uid}`,{days});await load();}finally{setBusy('')}};
 const setUserStatus=async(u:UserProfile,status:'active'|'disabled')=>{if(!confirm(`${status==='disabled'?'Disable':'Activate'} ${u.email}?`))return;setBusy(`status-${u.uid}`);try{await updateDoc(doc(db,'users',u.uid),{status});await writeAudit('status-change',`users/${u.uid}`,{status});await load();}finally{setBusy('')}};
 const activeChannels=useMemo(()=>channels.filter(x=>x.enabled).length,[channels]);const activeMedia=useMemo(()=>media.filter(x=>x.enabled).length,[media]);const dramas=useMemo(()=>media.filter(x=>x.type==='drama'),[media]);const films=useMemo(()=>media.filter(x=>x.type==='film'),[media]);const vipUsers=useMemo(()=>users.filter(u=>u.plan==='vip'),[users]);const freeUsers=useMemo(()=>users.filter(u=>u.status==='active'&&u.plan!=='vip'),[users]);const visibleUsers=useMemo(()=>userFilter==='vip'?vipUsers:userFilter==='free'?freeUsers:users,[userFilter,vipUsers,freeUsers,users]);
 if(!user)return <PageShell><div className="min-h-[50vh] grid place-items-center text-slate-400">Loading…</div></PageShell>;
 return <PageShell><Protected>{allowed?<div className="space-y-6 admin-shell">
  <div className="admin-hero"><div><div className="eyebrow"><ShieldCheck size={14}/> 4uSTREAM CONTROL CENTER</div><h1>Admin Studio</h1><p>Manage content, images, ads and VIP access from one place.</p></div><div className="admin-badge"><Crown size={15}/> Secure console</div></div>
  {message&&<div className="glass rounded-2xl p-3 flex items-center justify-between text-sm text-violet-200"><span>{message}</span><button onClick={()=>setMessage('')}><X size={16}/></button></div>}
  <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-3"><Stat label="Users" value={users.length}/><Stat label="VIP" value={vipUsers.length}/><Stat label="Channels" value={`${activeChannels}/${channels.length}`}/><Stat label="Media" value={`${activeMedia}/${media.length}`}/><Stat label="Episodes" value={episodes.length}/><Stat label="Parts" value={parts.length}/></div>
  <div className="flex flex-wrap gap-2"><Link href="/admin/branding" className="admin-secondary-btn"><ImageIcon size={15}/> Branding</Link><Link href="/admin/subtitles" className="admin-secondary-btn"><Clapperboard size={15}/> Subtitles</Link></div>
  <div className="admin-tabs">{[['dashboard','Dashboard',MonitorPlay],['users','Users',ShieldCheck],['channels','Channels',Radio],['media','Films & Drama',Film],['episodes','Episodes',Clapperboard],['parts','Film Parts',Layers],['ads','Ads',Megaphone],['audit','Audit',ShieldCheck]].map(([id,label,Icon]:any)=><button key={id} className={tab===id?'active':''} onClick={()=>setTab(id)}><Icon size={16}/>{label}</button>)}</div>
  {tab==='dashboard'&&<DashboardView users={users} channels={channels} media={media} episodes={episodes} vipUsers={vipUsers} setTab={setTab}/>}
  {tab==='users'&&<div className="space-y-4"><div className="admin-filter-panel"><div className="admin-filter-group"><span className="admin-filter-label">Members</span><div className="admin-filter-row"><FilterPill active={userFilter==='all'} onClick={()=>setUserFilter('all')}>All <b>{users.length}</b></FilterPill><FilterPill active={userFilter==='vip'} onClick={()=>setUserFilter('vip')} icon={<Crown size={14}/>}>VIP <b>{vipUsers.length}</b></FilterPill><FilterPill active={userFilter==='free'} onClick={()=>setUserFilter('free')} icon={<ShieldCheck size={14}/>}>Free <b>{freeUsers.length}</b></FilterPill></div></div></div><UserGroup title={userFilter==='all'?'All members':userFilter==='vip'?'VIP members':'Free members'} icon={userFilter==='vip'?Crown:ShieldCheck} accent={userFilter==='vip'?'vip':'free'} list={visibleUsers} setVip={setVip} setUserStatus={setUserStatus}/></div>}
  {tab==='channels'&&<ContentManager kind="channel" list={channels} form={channelForm} setForm={setChannelForm} editing={editingChannel} setEditing={setEditingChannel} save={()=>save('channel')} remove={remove}/>} 
  {tab==='media'&&<ContentManager kind="media" list={media} form={mediaForm} setForm={setMediaForm} editing={editingMedia} setEditing={setEditingMedia} save={()=>save('media')} remove={remove}/>} 
  {tab==='episodes'&&<EpisodeManager items={episodes} dramas={dramas} form={episodeForm} setForm={setEpisodeForm} editing={editingEpisode} setEditing={setEditingEpisode} save={()=>save('episode')} remove={remove} clear={clear}/>} 
  {tab==='parts'&&<PartsManager items={parts} films={films} form={partForm} setForm={setPartForm} editing={editingPart} setEditing={setEditingPart} save={()=>save('part')} remove={remove} clear={clear}/>} 
  {tab==='audit'&&<AuditView logs={auditLogs}/> }
  {tab==='ads'&&<AdManager items={ads} form={adForm} setForm={setAdForm} editing={editingAd} setEditing={setEditingAd} save={()=>save('ad')} remove={remove}/>} 
 </div>:<div className="min-h-[60vh] grid place-items-center text-slate-400">Not authorized.</div>}</Protected></PageShell>
}
function DashboardView({users,channels,media,episodes,vipUsers,setTab}:{users:UserProfile[];channels:Channel[];media:MediaItem[];episodes:DramaEpisode[];vipUsers:UserProfile[];setTab:(tab:'dashboard'|'users'|'channels'|'media'|'episodes'|'parts'|'ads'|'audit')=>void}){
 const activeChannels=channels.filter(x=>x.enabled).length; const activeMedia=media.filter(x=>x.enabled).length; const dramas=media.filter(x=>x.type==='drama').length; const films=media.filter(x=>x.type==='film').length;
 const cards=[['Users',users.length,'Registered members'],['VIP Members',vipUsers.length,'Premium access'],['Live TV',activeChannels,'Active channels'],['Content',activeMedia,'Published films & dramas'],['Episodes',episodes.length,'Series episodes'],['Films',films,'Movies'],['Drama',dramas,'Series']];
 return <div className="space-y-5">
   <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-3">{cards.map(([label,value,sub])=><div key={String(label)} className="dashboard-stat glass"><div className="text-[10px] uppercase tracking-widest text-slate-500">{label}</div><div className="text-2xl font-black mt-2">{value}</div><div className="text-[10px] text-slate-500 mt-1">{sub}</div></div>)}</div>
   <div className="grid lg:grid-cols-[1.4fr_.8fr] gap-5">
     <div className="glass rounded-3xl p-5"><div className="flex items-center justify-between"><div><div className="section-kicker">OVERVIEW</div><h2 className="text-xl font-black mt-1">4uStream control center</h2></div><div className="status-chip">Live data</div></div><div className="dashboard-chart"><div className="chart-line"><span/><span/><span/><span/><span/><span/><span/></div><div className="chart-labels"><span>Mon</span><span>Tue</span><span>Wed</span><span>Thu</span><span>Fri</span><span>Sat</span><span>Sun</span></div></div></div>
     <div className="glass rounded-3xl p-5"><div className="section-kicker">QUICK ACTIONS</div><div className="grid gap-2 mt-3"><QuickAdmin icon={<Film size={16}/>} label="Add movie / drama" onClick={()=>setTab('media')} target="media"/><QuickAdmin icon={<Clapperboard size={16}/>} label="Add episode" onClick={()=>setTab('episodes')} target="episodes"/><QuickAdmin icon={<Radio size={16}/>} label="Manage Live TV" onClick={()=>setTab('channels')} target="channels"/><QuickAdmin icon={<Megaphone size={16}/>} label="Manage ads" onClick={()=>setTab('ads')} target="ads"/><QuickAdmin icon={<ImageIcon size={16}/>} label="Branding Studio" onClick={()=>{}} target="branding"/></div></div>
   </div>
   <div className="glass rounded-3xl p-5"><div className="font-black">Mobile-first workflow</div><p className="text-sm text-slate-500 mt-2 leading-6">Images can be uploaded from the phone. Video files stay external: paste an authorized embed, HLS or video URL into the content form.</p></div>
 </div>
}
function AuditView({logs}:{logs:any[]}){return <div className="space-y-4"><div className="admin-section-toolbar"><div><div className="section-kicker">SECURITY</div><h2 className="admin-section-title">Audit Log</h2><p className="admin-section-note">Recent administrative changes are recorded for review.</p></div></div><div className="glass rounded-3xl overflow-hidden"><div className="divide-y divide-white/5">{logs.map((log:any)=><div key={log.id} className="p-4 flex flex-col sm:flex-row sm:items-center gap-2"><span className="access-chip vip">{String(log.action||'action')}</span><div className="min-w-0 flex-1"><div className="font-bold truncate">{log.target||'—'}</div><div className="text-xs text-slate-500 mt-1">Admin: {log.adminUid||'—'}</div></div><span className="text-xs text-slate-500">{formatDateTime(log.createdAt)}</span></div>)}{!logs.length&&<Empty text="No audit events yet."/>}</div></div></div>}
function formatDateTime(v:any){try{if(v?.toDate)return v.toDate().toLocaleString();const d=new Date(v);return Number.isNaN(d.getTime())?'—':d.toLocaleString()}catch{return '—'}}
function QuickAdmin({icon,label,onClick,target}:{icon:React.ReactNode;label:string;onClick:()=>void;target:string}){return target==='branding'?<Link href="/admin/branding" className="dashboard-action"><span>{icon}</span><b>{label}</b><small>{target}</small></Link>:<button type="button" onClick={onClick} className="dashboard-action"><span>{icon}</span><b>{label}</b><small>{target}</small></button>}
function Stat({label,value}:{label:string;value:any}){return <div className="glass rounded-2xl p-4"><div className="text-[10px] uppercase tracking-widest text-slate-500">{label}</div><div className="text-2xl font-black mt-1">{value}</div></div>}
function Empty({text}:{text:string}){return <div className="p-14 text-center text-slate-500">{text}</div>}
function formatDate(v:any){if(!v)return 'No expiry';try{return v?.toDate?v.toDate().toLocaleDateString():new Date(v).toLocaleDateString()}catch{return '—'}}
function UserGroup({title,icon:Icon,accent,list,setVip,setUserStatus}:any){return <div className={`glass rounded-3xl overflow-hidden ${accent==='vip'?'vip-group':''}`}><div className="p-5 border-b border-white/10 flex items-center justify-between"><div className="flex items-center gap-2"><Icon size={16} className={accent==='vip'?'text-violet-300':'text-slate-400'}/><h2 className="font-black">{title}</h2></div><span className="status-chip">{list.length}</span></div><div className="divide-y divide-white/5">{list.map((u:any)=><div key={u.uid} className="p-4 grid lg:grid-cols-[1fr_auto_auto] gap-4 items-center"><div><div className="font-bold flex items-center gap-2">{u.name}{u.plan==='vip'&&<span className="vip-chip"><Crown size={11}/>VIP</span>}</div><div className="text-xs text-slate-500 mt-1">{u.email}</div><div className="text-[10px] uppercase tracking-wider text-slate-600 mt-1">{u.status}</div>{u.plan==='vip'&&<div className="text-[11px] text-violet-300 mt-1">Expires: {formatDate(u.vipUntil)}</div>}</div><div className="flex gap-2 flex-wrap"><span className="status-chip">{u.plan==='vip'?'VIP':'FREE'}</span></div><div className="flex gap-2 flex-wrap"><button onClick={()=>setVip(u,30)} className="mini-btn vip-btn"><Crown size={15}/>VIP 30d</button><button onClick={()=>setVip(u,90)} className="mini-btn vip-btn"><Crown size={15}/>VIP 90d</button><button onClick={()=>setVip(u,null)} className="mini-btn"><X size={15}/>Free</button><button onClick={()=>setUserStatus(u,u.status==='disabled'?'active':'disabled')} className="mini-btn">{u.status==='disabled'?'Activate':'Disable'}</button></div></div>)}{!list.length&&<Empty text={accent==='vip'?'No VIP members yet.':'No free members.'}/>}</div></div>}
function Field({label,children}:{label:string;children:React.ReactNode}){return <label className="block"><span className="text-xs text-slate-400 font-bold">{label}</span><div className="mt-1 [&_input]:w-full [&_input]:rounded-xl [&_input]:px-3 [&_input]:py-2.5 [&_input]:outline-none [&_select]:w-full [&_select]:rounded-xl [&_select]:px-3 [&_select]:py-2.5 [&_select]:outline-none [&_textarea]:w-full [&_textarea]:rounded-xl [&_textarea]:px-3 [&_textarea]:py-2.5 [&_textarea]:outline-none [&_textarea]:min-h-20">{children}</div></label>}
function AccessField({value,onChange}:{value:AccessLevel;onChange:(v:AccessLevel)=>void}){return <Field label="Access"><select value={value||'free'} onChange={e=>onChange(e.target.value as AccessLevel)}><option value="free">FREE — active members</option><option value="vip">VIP — VIP members only</option></select></Field>}
function UploadField({label,value,onChange,folder}:{label:string;value:string;onChange:(v:string)=>void;folder:string}){const [busy,setBusy]=useState(false);const [err,setErr]=useState('');const upload=async(file?:File)=>{if(!file)return;if(!file.type.startsWith('image/')){setErr('Please choose an image file.');return}if(file.size>8*1024*1024){setErr('Max 8MB');return}setBusy(true);setErr('');try{onChange(await uploadAdminAsset(file,folder))}catch(e:any){setErr(e?.message||'Upload failed')}finally{setBusy(false)}};return <div><span className="text-xs text-slate-400 font-bold">{label}</span><div className="mt-1 flex flex-col sm:flex-row gap-2"><label className="upload-btn"><Upload size={15}/>{busy?'Uploading…':'Choose image'}<input type="file" accept="image/png,image/jpeg,image/webp,image/gif" className="hidden" onChange={e=>upload(e.target.files?.[0])}/></label><input value={value||''} onChange={e=>onChange(e.target.value)} placeholder="or paste image URL" inputMode="url"/></div>{value&&<img src={value} alt="preview" className="mt-2 h-20 w-full object-cover rounded-xl border border-white/10"/>}{err&&<div className="text-xs text-red-300 mt-1">{err}</div>}</div>}
function AdminFormModal({title,subtitle,onClose,children}:{title:string;subtitle?:string;onClose:()=>void;children:React.ReactNode}){
 return <div className="admin-modal-backdrop" role="dialog" aria-modal="true">
  <div className="admin-modal">
   <div className="admin-modal-head"><div><div className="section-kicker">EDITOR</div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div><button className="icon-btn" onClick={onClose} aria-label="Close"><X size={18}/></button></div>
   <div className="admin-modal-body">{children}</div>
  </div>
 </div>
}
function FilterPill({active,onClick,children,icon}:{active:boolean;onClick:()=>void;children:React.ReactNode;icon?:React.ReactNode}){
 return <button type="button" className={`admin-filter ${active?'active':''}`} onClick={onClick}>{icon}{children}</button>
}
function ContentManager({kind,list,form,setForm,editing,setEditing,save,remove}:any){
 const isChannel=kind==='channel';
 const [showForm,setShowForm]=useState(false);
 const [typeFilter,setTypeFilter]=useState<'all'|'film'|'drama'>('all');
 const [accessFilter,setAccessFilter]=useState<'all'|'free'|'vip'>('all');
 const [section,setSection]=useState<'basic'|'artwork'|'playback'|'metadata'|'people'|'seo'>('basic');
 const [galleryText,setGalleryText]=useState('');
 const [castText,setCastText]=useState('');
 const [serverText,setServerText]=useState('');
 const [subtitleText,setSubtitleText]=useState('');
 const [busy,setBusy]=useState(false);

 const hydrateEditor=(x:any)=>{
  setForm({...x,accessLevel:x.accessLevel||'free'});
  setGalleryText((x.images||[]).filter((i:any)=>i?.url).map((i:any)=>i.url).join('\n'));
  setCastText((x.cast||[]).map((c:any)=>`${c.name||''}${c.character?` | ${c.character}`:''}`).join('\n'));
  setServerText((x.servers||[]).map((s:any)=>[s.name||'',s.url||'',s.playerType||'iframe',s.quality||'',s.accessLevel||'free',s.enabled===false?'off':'on'].join(' | ')).join('\n'));
  setSubtitleText((x.subtitles||[]).map((t:any)=>[t.label||'',t.language||'',t.src||'',t.default?'default':''].join(' | ')).join('\n'));
 };
 const edit=(x:any)=>{setEditing(x.id);hydrateEditor(x);setSection('basic');setShowForm(true)};
 const addNew=()=>{setEditing(null);setForm(isChannel?{...emptyChannel}:{...emptyMedia});setGalleryText('');setCastText('');setServerText('');setSubtitleText('');setSection('basic');setShowForm(true)};
 const closeForm=()=>{setShowForm(false);setEditing(null);setForm(isChannel?{...emptyChannel}:{...emptyMedia});setGalleryText('');setCastText('');setServerText('');setSubtitleText('')};
 const visible=list.filter((x:any)=>{
  const typeOk=isChannel||typeFilter==='all'||x.type===typeFilter;
  const access=(x.accessLevel||'free')==='vip'?'vip':'free';
  return typeOk&&(accessFilter==='all'||access===accessFilter);
 });
 const filmsCount=list.filter((x:any)=>x.type==='film').length;
 const dramasCount=list.filter((x:any)=>x.type==='drama').length;
 const vipCount=list.filter((x:any)=>(x.accessLevel||'free')==='vip').length;
 const freeCount=list.length-vipCount;
 const setArray=(key:string,text:string)=>{
  const lines=text.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);
  if(key==='images') setForm({...form,images:lines.map((url:string,i:number)=>({url,type:'screenshot',order:i}))});
  if(key==='cast') setForm({...form,cast:lines.map((line:string,i:number)=>{const [name,...rest]=line.split('|').map(x=>x.trim());return {name,character:rest.join(' | ')||undefined,order:i}}).filter((x:any)=>x.name)});
  if(key==='servers') setForm({...form,servers:lines.map((line:string,i:number)=>{const [name,url,playerType,quality,accessLevel,enabled]=line.split('|').map(x=>x.trim());return {id:`server-${i+1}`,name:name||`Server ${i+1}`,url:url||'',playerType:(playerType||'iframe') as PlayerType,quality:quality||undefined,accessLevel:(accessLevel==='vip'?'vip':'free') as AccessLevel,enabled:enabled!=='off'}}).filter((x:any)=>x.url)});
  if(key==='subtitles') setForm({...form,subtitles:lines.map((line:string,i:number)=>{const [label,language,src,def]=line.split('|').map(x=>x.trim());return {id:`sub-${i+1}`,label:label||language||`Subtitle ${i+1}`,language:language||'ku',src:src||'',default:def==='default'}}).filter((x:any)=>x.src)});
 };
 const commit=async()=>{
  setBusy(true);
  try { await save(); setShowForm(false); }
  finally { setBusy(false); }
 };
 const Row=(item:any)=><div key={item.id} className="admin-content-row">
  <div className="admin-thumb">{(isChannel?item.logo:item.poster)?<img src={isChannel?item.logo:item.poster} alt=""/>:<ImageIcon size={18} className="text-violet-300"/>}</div>
  <div className="min-w-0 flex-1"><div className="font-bold truncate">{isChannel?item.name:item.title}</div><div className="text-xs text-slate-500 mt-1">{isChannel?item.category:`${item.type==='film'?'Film':'Drama'} · ${item.year}`} · {item.enabled?'Active':'Off'}{item.quality?.length?` · ${item.quality.join(', ')}`:''}</div></div>
  <span className={`access-chip ${item.accessLevel==='vip'?'vip':'free'}`}>{item.accessLevel==='vip'?'VIP':'FREE'}</span>
  <button onClick={()=>edit(item)} className="icon-btn" aria-label="Edit"><Edit3 size={16}/></button>
  <button onClick={()=>remove(isChannel?'channels':'media',item.id)} className="icon-btn text-red-300" aria-label="Delete"><Trash2 size={16}/></button>
 </div>;
 const tabs=[['basic','Basics'],['artwork','Artwork'],['playback','Playback'],['metadata','Metadata'],['people','Cast & crew'],['seo','SEO']];
 return <div className="space-y-4">
  <div className="admin-section-toolbar"><div><div className="section-kicker">{isChannel?'LIVE TV':'LIBRARY'}</div><h2 className="admin-section-title">{isChannel?'Channels':'Films & Drama'}</h2><p className="admin-section-note">Professional content management with artwork, metadata, playback, subtitles and SEO.</p></div><button onClick={addNew} className="admin-primary-btn"><Plus size={17}/>{isChannel?'Add channel':'Add film / drama'}</button></div>
  <div className="admin-filter-panel">
   {!isChannel&&<div className="admin-filter-group"><span className="admin-filter-label">Content</span><div className="admin-filter-row"><FilterPill active={typeFilter==='all'} onClick={()=>setTypeFilter('all')} icon={<Film size={14}/>}>All <b>{list.length}</b></FilterPill><FilterPill active={typeFilter==='film'} onClick={()=>setTypeFilter('film')} icon={<Film size={14}/>}>Films <b>{filmsCount}</b></FilterPill><FilterPill active={typeFilter==='drama'} onClick={()=>setTypeFilter('drama')} icon={<Clapperboard size={14}/>}>Drama <b>{dramasCount}</b></FilterPill></div></div>}
   <div className="admin-filter-group"><span className="admin-filter-label">Access</span><div className="admin-filter-row"><FilterPill active={accessFilter==='all'} onClick={()=>setAccessFilter('all')}>All <b>{list.length}</b></FilterPill><FilterPill active={accessFilter==='free'} onClick={()=>setAccessFilter('free')} icon={<ShieldCheck size={14}/>}>Free <b>{freeCount}</b></FilterPill><FilterPill active={accessFilter==='vip'} onClick={()=>setAccessFilter('vip')} icon={<Crown size={14}/>}>VIP <b>{vipCount}</b></FilterPill></div></div>
  </div>
  <div className="glass rounded-3xl overflow-hidden"><div className="admin-list-head"><div><b>{isChannel?'Channels':'Content'}</b><span>{visible.length} shown</span></div><button onClick={addNew} className="list-add-btn"><Plus size={14}/>Add</button></div><div className="divide-y divide-white/5">{visible.map(Row)}{!visible.length&&<Empty text={isChannel?'No channels match this filter.':'No films or dramas match this filter.'}/>}</div></div>
  {showForm&&<AdminFormModal title={`${editing?'Edit':'Add'} ${isChannel?'channel':'film / drama'}`} subtitle="Build a complete catalog entry. Video files stay external; paste an authorized URL or embed address." onClose={closeForm}>
   <div className="space-y-5">
    {!isChannel&&<div className="studio-tabs">{tabs.map(([id,label])=><button key={id} type="button" className={section===id?'active':''} onClick={()=>setSection(id as any)}>{label}</button>)}</div>}
    {isChannel&&<div className="glass rounded-2xl p-4 text-sm text-slate-400">Live channel editor</div>}
    {isChannel?<div className="grid sm:grid-cols-2 gap-4">
      <Field label="ID"><input value={form.id} disabled={!!editing} onChange={e=>setForm({...form,id:e.target.value})}/></Field>
      <Field label="Name"><input value={form.name||''} onChange={e=>setForm({...form,name:e.target.value})}/></Field>
      <Field label="Category"><select value={form.category||'NEWS'} onChange={e=>setForm({...form,category:e.target.value})}>{categories.map(c=><option key={c}>{c}</option>)}</select></Field>
      <AccessField value={form.accessLevel||'free'} onChange={v=>setForm({...form,accessLevel:v})}/>
      <UploadField label="Channel logo" value={form.logo||''} onChange={v=>setForm({...form,logo:v})} folder="logos"/>
      <Field label="Player"><select value={form.playerType||'video'} onChange={e=>setForm({...form,playerType:e.target.value as PlayerType})}><option value="video">VIDEO / MP4</option><option value="hls">HLS / M3U8</option><option value="iframe">IFRAME / Embed</option></select></Field>
      <div className="sm:col-span-2"><Field label="Stream / embed URL"><input value={form.streamUrl||''} onChange={e=>setForm({...form,streamUrl:e.target.value})} placeholder="https://..." inputMode="url"/></Field></div>
      <div className="sm:col-span-2"><Field label="Description"><textarea value={form.description||''} onChange={e=>setForm({...form,description:e.target.value})}/></Field></div>
    </div>:<>
      {section==='basic'&&<div className="grid sm:grid-cols-2 gap-4">
       <Field label="ID / slug key"><input value={form.id} disabled={!!editing} onChange={e=>setForm({...form,id:e.target.value})}/></Field>
       <Field label="Title"><input value={form.title||''} onChange={e=>setForm({...form,title:e.target.value})}/></Field>
       <Field label="Content type"><select value={form.type||'film'} onChange={e=>setForm({...form,type:e.target.value})}><option value="film">Film</option><option value="drama">Drama / Series</option></select></Field>
       <Field label="Slug"><input value={form.slug||''} onChange={e=>setForm({...form,slug:e.target.value})} placeholder="auto-generated-if-empty"/></Field>
       <Field label="Release year"><input type="number" min="1900" max="2100" value={form.year||new Date().getFullYear()} onChange={e=>setForm({...form,year:Number(e.target.value)})}/></Field>
       <Field label="Release date"><input type="date" value={form.releaseDate||''} onChange={e=>setForm({...form,releaseDate:e.target.value})}/></Field>
       <Field label="Primary genre"><input value={form.genre||''} onChange={e=>setForm({...form,genre:e.target.value})} placeholder="Action, Drama..."/></Field>
       <Field label="Country"><input value={form.country||''} onChange={e=>setForm({...form,country:e.target.value})} placeholder="Turkey, Kurdistan..."/></Field>
       <Field label="Original language"><input value={form.originalLanguage||''} onChange={e=>setForm({...form,originalLanguage:e.target.value})} placeholder="tr / ku / en..."/></Field>
       <Field label="Age rating"><input value={form.ageRating||''} onChange={e=>setForm({...form,ageRating:e.target.value})} placeholder="13+ / 16+ / 18+"/></Field>
       <AccessField value={form.accessLevel||'free'} onChange={v=>setForm({...form,accessLevel:v})}/>
       <Field label="Status"><select value={form.status||'released'} onChange={e=>setForm({...form,status:e.target.value})}><option value="released">Released</option><option value="ongoing">Ongoing</option><option value="upcoming">Upcoming</option><option value="completed">Completed</option></select></Field>
       <div className="sm:col-span-2"><Field label="Description"><textarea className="min-h-32" value={form.description||''} onChange={e=>setForm({...form,description:e.target.value})}/></Field></div>
       <Field label="Published"><label className="flex items-center gap-3 h-11 px-3 rounded-xl border border-white/10"><input type="checkbox" checked={!!form.enabled} onChange={e=>setForm({...form,enabled:e.target.checked})}/><span className="text-sm font-bold">Visible on public catalog</span></label></Field>
      </div>}
      {section==='artwork'&&<div className="grid sm:grid-cols-2 gap-4">
       <UploadField label="Poster / cover" value={form.poster||''} onChange={v=>setForm({...form,poster:v})} folder="posters"/>
       <UploadField label="Backdrop / hero image" value={form.backdrop||''} onChange={v=>setForm({...form,backdrop:v})} folder="backdrops"/>
       <UploadField label="Transparent logo" value={form.logo||''} onChange={v=>setForm({...form,logo:v})} folder="logos"/>
       <Field label="Trailer URL"><input value={form.trailerUrl||''} onChange={e=>setForm({...form,trailerUrl:e.target.value})} placeholder="https://..." inputMode="url"/></Field>
       <Field label="Trailer player"><select value={form.trailerPlayerType||'iframe'} onChange={e=>setForm({...form,trailerPlayerType:e.target.value as PlayerType})}><option value="iframe">IFRAME / Embed</option><option value="video">VIDEO / MP4</option><option value="hls">HLS / M3U8</option></select></Field>
       <div className="sm:col-span-2"><Field label="Screenshots / gallery URLs"><textarea value={galleryText} onChange={e=>{setGalleryText(e.target.value);setArray('images',e.target.value)}} placeholder="One image URL per line"/></Field></div>
       <div className="sm:col-span-2 grid sm:grid-cols-2 gap-4"><div className="glass rounded-2xl p-4"><div className="font-bold text-sm">Artwork preview</div>{form.poster?<img src={form.poster} alt="Poster preview" className="mt-3 h-48 w-full rounded-xl object-cover"/>:<div className="mt-3 h-48 rounded-xl grid place-items-center text-slate-500 bg-white/[.03]">No poster</div>}</div><div className="glass rounded-2xl p-4"><div className="font-bold text-sm">Backdrop preview</div>{form.backdrop?<img src={form.backdrop} alt="Backdrop preview" className="mt-3 h-48 w-full rounded-xl object-cover"/>:<div className="mt-3 h-48 rounded-xl grid place-items-center text-slate-500 bg-white/[.03]">No backdrop</div>}</div></div>
      </div>}
      {section==='playback'&&<div className="space-y-4">
       <div className="glass rounded-2xl p-4 grid sm:grid-cols-2 gap-4"><Field label="Primary player"><select value={form.playerType||'video'} onChange={e=>setForm({...form,playerType:e.target.value as PlayerType})}><option value="video">VIDEO / MP4</option><option value="hls">HLS / M3U8</option><option value="iframe">IFRAME / Embed</option></select></Field><Field label={form.playerType==='iframe'?'Primary embed URL':form.playerType==='hls'?'Primary HLS URL':'Primary video URL'}><input value={form.streamUrl||''} onChange={e=>setForm({...form,streamUrl:e.target.value})} placeholder="https://..." inputMode="url"/></Field><Field label="Skip intro (seconds)"><input type="number" min="0" value={form.skipIntroSeconds||0} onChange={e=>setForm({...form,skipIntroSeconds:Math.max(0,Number(e.target.value)||0)})}/></Field><Field label="Quality labels"><input value={(form.quality||[]).join(', ')} onChange={e=>setForm({...form,quality:e.target.value.split(',').map((x:string)=>x.trim()).filter(Boolean)})} placeholder="360p, 720p, 1080p, 4K"/></Field></div>
       <div className="glass rounded-2xl p-4"><div className="font-bold">Multiple servers</div><p className="text-xs text-slate-500 mt-1">One per line: <code>Name | URL | Player | Quality | Access | on/off</code></p><textarea className="mt-3 min-h-32" value={serverText} onChange={e=>{setServerText(e.target.value);setArray('servers',e.target.value)}} placeholder="VidMoly | https://... | iframe | 1080p | free | on"/></div>
       <div className="glass rounded-2xl p-4"><div className="font-bold">Subtitles</div><p className="text-xs text-slate-500 mt-1">One per line: <code>Label | Language | VTT URL | default</code></p><textarea className="mt-3 min-h-32" value={subtitleText} onChange={e=>{setSubtitleText(e.target.value);setArray('subtitles',e.target.value)}} placeholder="Badini | ku | https://.../badini.vtt | default"/></div>
      </div>}
      {section==='metadata'&&<div className="grid sm:grid-cols-2 gap-4">
       <Field label="Rating (0–10)"><input type="number" min="0" max="10" step="0.1" value={form.rating??''} onChange={e=>setForm({...form,rating:e.target.value===''?undefined:Math.min(10,Math.max(0,Number(e.target.value)))})}/></Field>
       <Field label="Rating count"><input type="number" min="0" value={form.ratingCount||0} onChange={e=>setForm({...form,ratingCount:Math.max(0,Number(e.target.value)||0)})}/></Field>
       <Field label="Runtime (minutes)"><input type="number" min="0" value={form.runtimeMinutes||0} onChange={e=>setForm({...form,runtimeMinutes:Math.max(0,Number(e.target.value)||0)})}/></Field>
       <Field label="IMDb ID"><input value={form.imdbId||''} onChange={e=>setForm({...form,imdbId:e.target.value})} placeholder="tt1234567"/></Field>
       <Field label="Genres"><input value={(form.genres||[]).join(', ')} onChange={e=>setForm({...form,genres:e.target.value.split(',').map((x:string)=>x.trim()).filter(Boolean)})} placeholder="Action, Drama, Thriller"/></Field>
       <Field label="Tags"><input value={(form.tags||[]).join(', ')} onChange={e=>setForm({...form,tags:e.target.value.split(',').map((x:string)=>x.trim()).filter(Boolean)})} placeholder="Turkish, 2026, HD"/></Field>
       <div className="sm:col-span-2"><Field label="Cast (one per line)"><textarea className="min-h-32" value={castText} onChange={e=>{setCastText(e.target.value);setArray('cast',e.target.value)}} placeholder="Actor Name | Character Name"/></Field></div>
      </div>}
      {section==='people'&&<div className="grid sm:grid-cols-2 gap-4"><Field label="Director"><input value={form.director||''} onChange={e=>setForm({...form,director:e.target.value})}/></Field><Field label="IMDb ID"><input value={form.imdbId||''} onChange={e=>setForm({...form,imdbId:e.target.value})}/></Field><div className="sm:col-span-2"><Field label="Cast / characters"><textarea className="min-h-44" value={castText} onChange={e=>{setCastText(e.target.value);setArray('cast',e.target.value)}} placeholder="Actor Name | Character Name"/></Field></div></div>}
      {section==='seo'&&<div className="grid gap-4"><Field label="SEO title"><input value={form.seoTitle||''} onChange={e=>setForm({...form,seoTitle:e.target.value})}/></Field><Field label="SEO description"><textarea value={form.seoDescription||''} onChange={e=>setForm({...form,seoDescription:e.target.value})}/></Field><Field label="Keywords"><input value={(form.keywords||[]).join(', ')} onChange={e=>setForm({...form,keywords:e.target.value.split(',').map((x:string)=>x.trim()).filter(Boolean)})} placeholder="film, drama, kurdish, subtitles"/></Field><div className="glass rounded-2xl p-4 text-xs text-slate-500">SEO fields are stored with the title so the public detail page can use them later without changing the content model.</div></div>}
     </>}
    <div className="sticky bottom-0 -mx-1 mt-2 border-t border-white/10 bg-slate-950/95 backdrop-blur-xl pt-3 flex flex-col sm:flex-row gap-2"><button onClick={closeForm} type="button" className="admin-secondary-btn flex-1">Cancel</button><button onClick={commit} type="button" disabled={busy} className="admin-primary-btn flex-1"><Save size={16}/>{busy?'Saving…':editing?'Save changes':'Create content'}</button></div>
   </div>
  </AdminFormModal>}
 </div>
}
function EpisodeManager({items,dramas,form,setForm,editing,setEditing,save,remove,clear}:any){
 const [showForm,setShowForm]=useState(false); const [accessFilter,setAccessFilter]=useState<'all'|'free'|'vip'>('all');
 const edit=(x:any)=>{setForm({...x,accessLevel:x.accessLevel||'free'});setEditing(x.id);setShowForm(true)};
 const addNew=()=>{clear('episode',{dramaId:form.dramaId||''});setShowForm(true)};
 const closeForm=()=>{setShowForm(false);setEditing(null);clear('episode')};
 const selectedDrama=dramas.find((d:any)=>d.id===form.dramaId);
 const scoped=items.filter((x:any)=>x.dramaId===form.dramaId&&(accessFilter==='all'||(x.accessLevel||'free')===accessFilter)).sort((a:any,b:any)=>a.seasonNumber-b.seasonNumber||a.episodeNumber-b.episodeNumber);
 const base=items.filter((x:any)=>x.dramaId===form.dramaId); const free=base.filter((x:any)=>(x.accessLevel||'free')==='free').length; const vip=base.length-free;
 return <div className="space-y-4">
  <div className="admin-section-toolbar"><div><div className="section-kicker">SERIES</div><h2 className="admin-section-title">Episodes</h2><p className="admin-section-note">Choose a drama and access level before opening the editor.</p></div><button onClick={addNew} className="admin-primary-btn"><Plus size={17}/>Add episode</button></div>
  <div className="admin-filter-panel"><Field label="Drama"><select value={form.dramaId} onChange={e=>setForm({...form,dramaId:e.target.value})}><option value="">Select drama</option>{dramas.map((d:any)=><option key={d.id} value={d.id}>{d.title}</option>)}</select></Field><div className="admin-filter-group"><span className="admin-filter-label">Access</span><div className="admin-filter-row"><FilterPill active={accessFilter==='all'} onClick={()=>setAccessFilter('all')}>All <b>{base.length}</b></FilterPill><FilterPill active={accessFilter==='free'} onClick={()=>setAccessFilter('free')} icon={<ShieldCheck size={14}/>}>Free <b>{free}</b></FilterPill><FilterPill active={accessFilter==='vip'} onClick={()=>setAccessFilter('vip')} icon={<Crown size={14}/>}>VIP <b>{vip}</b></FilterPill></div></div></div>
  <div className="glass rounded-3xl overflow-hidden"><div className="admin-list-head"><div><b>{selectedDrama?selectedDrama.title:'Episodes'}</b><span>{selectedDrama?`${scoped.length} shown`:'Select a drama'}</span></div>{form.dramaId&&<button onClick={addNew} className="list-add-btn"><Plus size={14}/>Add</button>}</div>{!form.dramaId?<Empty text="Select a drama to see its episodes."/>:<div className="divide-y divide-white/5">{scoped.map((x:any)=><div key={x.id} className="admin-content-row"><div className="admin-thumb">{x.thumbnail?<img src={x.thumbnail} alt=""/>:<span className="font-black text-violet-300">{String(x.episodeNumber).padStart(2,'0')}</span>}</div><div className="min-w-0 flex-1"><div className="font-bold truncate">{x.title}</div><div className="text-xs text-slate-500 mt-1">S{x.seasonNumber} · {x.durationMinutes||0} min · {x.enabled?'Active':'Off'}</div></div><span className={`access-chip ${x.accessLevel==='vip'?'vip':'free'}`}>{x.accessLevel==='vip'?'VIP':'FREE'}</span><button onClick={()=>edit(x)} className="icon-btn"><Edit3 size={16}/></button><button onClick={()=>remove('episodes',x.id)} className="icon-btn text-red-300"><Trash2 size={16}/></button></div>)}{!scoped.length&&<Empty text="No episodes match this filter."/>}</div>}</div>
  {showForm&&<AdminFormModal title={`${editing?'Edit':'Add'} episode`} subtitle="Add the thumbnail and paste an external video / HLS / embed URL." onClose={closeForm}><div className="space-y-4"><Field label="Drama"><select value={form.dramaId} onChange={e=>setForm({...form,dramaId:e.target.value})}><option value="">Select drama</option>{dramas.map((d:any)=><option key={d.id} value={d.id}>{d.title}</option>)}</select></Field><Field label="Episode title"><input value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></Field><div className="grid grid-cols-2 gap-3"><Field label="Season"><input type="number" min="1" value={form.seasonNumber} onChange={e=>setForm({...form,seasonNumber:Number(e.target.value)})}/></Field><Field label="Episode"><input type="number" min="1" value={form.episodeNumber} onChange={e=>setForm({...form,episodeNumber:Number(e.target.value)})}/></Field></div><Field label="Duration (minutes)"><input type="number" min="0" value={form.durationMinutes||0} onChange={e=>setForm({...form,durationMinutes:Number(e.target.value)})}/></Field><UploadField label="Episode thumbnail" value={form.thumbnail||''} onChange={v=>setForm({...form,thumbnail:v})} folder="episodes"/><Field label="Description"><textarea value={form.description||''} onChange={e=>setForm({...form,description:e.target.value})}/></Field><Field label="Player"><select value={form.playerType||'video'} onChange={e=>setForm({...form,playerType:e.target.value as PlayerType})}><option value="video">VIDEO / MP4</option><option value="hls">HLS / M3U8</option><option value="iframe">IFRAME / Embed</option></select></Field><Field label={form.playerType==='iframe'?'Embed URL':form.playerType==='hls'?'HLS / M3U8 URL':'Video / MP4 URL'}><input value={form.streamUrl||''} onChange={e=>setForm({...form,streamUrl:e.target.value})} placeholder={form.playerType==='iframe'?'https://.../embed-...html':form.playerType==='hls'?'https://.../master.m3u8':'https://.../movie.mp4'} inputMode="url"/></Field><AccessField value={form.accessLevel||'free'} onChange={v=>setForm({...form,accessLevel:v})}/><label className="flex items-center gap-3 text-sm font-bold"><input type="checkbox" checked={!!form.enabled} onChange={e=>setForm({...form,enabled:e.target.checked})}/><span>Published / active</span></label><div className="flex gap-2"><button onClick={closeForm} className="admin-secondary-btn flex-1">Cancel</button><button onClick={async()=>{await save();setShowForm(false)}} className="admin-primary-btn flex-1">{editing?'Save changes':'Add episode'}</button></div></div></AdminFormModal>}
 </div>
}
function PartsManager({items,films,form,setForm,editing,setEditing,save,remove,clear}:any){
 const [showForm,setShowForm]=useState(false); const [accessFilter,setAccessFilter]=useState<'all'|'free'|'vip'>('all');
 const edit=(x:any)=>{setForm({...x,accessLevel:x.accessLevel||'free'});setEditing(x.id);setShowForm(true)};
 const addNew=()=>{clear('part',{mediaId:form.mediaId||''});setShowForm(true)};
 const closeForm=()=>{setShowForm(false);setEditing(null);clear('part')};
 const selectedFilm=films.find((f:any)=>f.id===form.mediaId); const base=items.filter((x:any)=>x.mediaId===form.mediaId); const scoped=base.filter((x:any)=>accessFilter==='all'||(x.accessLevel||'free')===accessFilter).sort((a:any,b:any)=>a.partNumber-b.partNumber); const free=base.filter((x:any)=>(x.accessLevel||'free')==='free').length; const vip=base.length-free;
 return <div className="space-y-4"><div className="admin-section-toolbar"><div><div className="section-kicker">FILM PARTS</div><h2 className="admin-section-title">Film Parts</h2><p className="admin-section-note">Select a film and access level, then edit only the parts you need.</p></div><button onClick={addNew} className="admin-primary-btn"><Plus size={17}/>Add part</button></div><div className="admin-filter-panel"><Field label="Film"><select value={form.mediaId} onChange={e=>setForm({...form,mediaId:e.target.value})}><option value="">Select film</option>{films.map((f:any)=><option key={f.id} value={f.id}>{f.title}</option>)}</select></Field><div className="admin-filter-group"><span className="admin-filter-label">Access</span><div className="admin-filter-row"><FilterPill active={accessFilter==='all'} onClick={()=>setAccessFilter('all')}>All <b>{base.length}</b></FilterPill><FilterPill active={accessFilter==='free'} onClick={()=>setAccessFilter('free')} icon={<ShieldCheck size={14}/>}>Free <b>{free}</b></FilterPill><FilterPill active={accessFilter==='vip'} onClick={()=>setAccessFilter('vip')} icon={<Crown size={14}/>}>VIP <b>{vip}</b></FilterPill></div></div></div><div className="glass rounded-3xl overflow-hidden"><div className="admin-list-head"><div><b>{selectedFilm?selectedFilm.title:'Film Parts'}</b><span>{selectedFilm?`${scoped.length} shown`:'Select a film'}</span></div>{form.mediaId&&<button onClick={addNew} className="list-add-btn"><Plus size={14}/>Add</button>}</div>{!form.mediaId?<Empty text="Select a film to see its parts."/>:<div className="divide-y divide-white/5">{scoped.map((x:any)=><div key={x.id} className="admin-content-row"><div className="admin-thumb grid place-items-center font-black text-violet-300">{String(x.partNumber).padStart(2,'0')}</div><div className="min-w-0 flex-1"><div className="font-bold truncate">{x.title||`Part ${x.partNumber}`}</div><div className="text-xs text-slate-500 mt-1">{x.durationMinutes||0} min · {x.enabled?'Active':'Off'}</div></div><span className={`access-chip ${x.accessLevel==='vip'?'vip':'free'}`}>{x.accessLevel==='vip'?'VIP':'FREE'}</span><button onClick={()=>edit(x)} className="icon-btn"><Edit3 size={16}/></button><button onClick={()=>remove('parts',x.id)} className="icon-btn text-red-300"><Trash2 size={16}/></button></div>)}{!scoped.length&&<Empty text="No parts match this filter."/>}</div>}</div>{showForm&&<AdminFormModal title={`${editing?'Edit':'Add'} film part`} subtitle="Video files stay external. Paste the authorized URL or embed address." onClose={closeForm}><div className="space-y-4"><Field label="Film"><select value={form.mediaId} onChange={e=>setForm({...form,mediaId:e.target.value})}><option value="">Select film</option>{films.map((f:any)=><option key={f.id} value={f.id}>{f.title}</option>)}</select></Field><Field label="Part number"><input type="number" min="1" value={form.partNumber} onChange={e=>setForm({...form,partNumber:Number(e.target.value)})}/></Field><Field label="Part title (optional)"><input value={form.title||''} onChange={e=>setForm({...form,title:e.target.value})} placeholder={`Part ${form.partNumber||1}`}/></Field><Field label="Duration (minutes)"><input type="number" min="0" value={form.durationMinutes||0} onChange={e=>setForm({...form,durationMinutes:Number(e.target.value)})}/></Field><Field label="Player"><select value={form.playerType||'video'} onChange={e=>setForm({...form,playerType:e.target.value as PlayerType})}><option value="video">VIDEO / MP4</option><option value="hls">HLS / M3U8</option><option value="iframe">IFRAME / Embed</option></select></Field><Field label={form.playerType==='iframe'?'Embed URL':form.playerType==='hls'?'HLS / M3U8 URL':'Video / MP4 URL'}><input value={form.streamUrl||''} onChange={e=>setForm({...form,streamUrl:e.target.value})} placeholder="https://..." inputMode="url"/></Field><AccessField value={form.accessLevel||'free'} onChange={v=>setForm({...form,accessLevel:v})}/><label className="flex items-center gap-3 text-sm font-bold"><input type="checkbox" checked={!!form.enabled} onChange={e=>setForm({...form,enabled:e.target.checked})}/><span>Published / active</span></label><div className="flex gap-2"><button onClick={closeForm} className="admin-secondary-btn flex-1">Cancel</button><button onClick={async()=>{await save();setShowForm(false)}} className="admin-primary-btn flex-1">{editing?'Save changes':'Add part'}</button></div></div></AdminFormModal>}</div>
}
function AdManager({items,form,setForm,editing,setEditing,save,remove}:any){
 const [showForm,setShowForm]=useState(false); const [placementFilter,setPlacementFilter]=useState<'all'|'banner'|'popup'|'inline'>('all'); const [audienceFilter,setAudienceFilter]=useState<'all'|'free'|'vip'>('all');
 const edit=(x:any)=>{setForm({...emptyAd,...x});setEditing(x.id);setShowForm(true)}; const addNew=()=>{setEditing(null);setForm({...emptyAd});setShowForm(true)}; const closeForm=()=>{setShowForm(false);setEditing(null);setForm({...emptyAd})}; const visible=items.filter((x:any)=>(placementFilter==='all'||(x.placement||'banner')===placementFilter)&&(audienceFilter==='all'||(x.audience||'all')===audienceFilter));
 return <div className="space-y-4"><div className="admin-section-toolbar"><div><div className="section-kicker">MONETIZATION</div><h2 className="admin-section-title">Advertisements</h2><p className="admin-section-note">Schedule, target and control banner/popup campaigns without redeploying.</p></div><button onClick={addNew} className="admin-primary-btn"><Plus size={17}/>Add advertisement</button></div><div className="admin-filter-panel"><div className="admin-filter-group"><span className="admin-filter-label">Placement</span><div className="admin-filter-row"><FilterPill active={placementFilter==='all'} onClick={()=>setPlacementFilter('all')}>All <b>{items.length}</b></FilterPill><FilterPill active={placementFilter==='banner'} onClick={()=>setPlacementFilter('banner')} icon={<MonitorPlay size={14}/>}>Banner</FilterPill><FilterPill active={placementFilter==='popup'} onClick={()=>setPlacementFilter('popup')} icon={<MousePointerClick size={14}/>}>Popup</FilterPill><FilterPill active={placementFilter==='inline'} onClick={()=>setPlacementFilter('inline')} icon={<LayoutTemplate size={14}/>}>Inline</FilterPill></div></div><div className="admin-filter-group"><span className="admin-filter-label">Audience</span><div className="admin-filter-row"><FilterPill active={audienceFilter==='all'} onClick={()=>setAudienceFilter('all')}>All</FilterPill><FilterPill active={audienceFilter==='free'} onClick={()=>setAudienceFilter('free')}>Free</FilterPill><FilterPill active={audienceFilter==='vip'} onClick={()=>setAudienceFilter('vip')}>VIP</FilterPill></div></div></div><div className="grid md:grid-cols-2 gap-4">{visible.map((x:any)=><div key={x.id} className="glass rounded-3xl overflow-hidden"><div className="relative"><img src={x.image} alt={x.title} className="w-full h-40 object-cover"/><div className="absolute top-3 start-3 ad-type"><PlacementIcon type={x.placement}/>{x.placement||'banner'}</div></div><div className="p-4"><div className="font-bold truncate">{x.title}</div><div className="flex flex-wrap gap-2 mt-2 text-[10px]"><span className="access-chip">{x.audience||'all'} audience</span><span className="access-chip">priority {x.priority??0}</span><span className="access-chip">{x.frequencySeconds??20}s frequency</span>{(x.placement||'banner')==='popup'&&<span className="access-chip">skip {x.skipAfterSeconds??5}s</span>}</div><div className="text-xs text-slate-500 mt-2">Order {x.order} · {x.enabled?'Active':'Disabled'}{x.startAt?' · starts '+String(x.startAt):''}{x.endAt?' · ends '+String(x.endAt):''}</div><div className="flex gap-2 mt-3"><button onClick={()=>edit(x)} className="icon-btn"><Edit3 size={16}/></button><button onClick={()=>remove('ads',x.id)} className="icon-btn text-red-300"><Trash2 size={16}/></button></div></div></div>)}{!visible.length&&<div className="glass rounded-3xl md:col-span-2"><Empty text="No advertisements match this filter."/></div>}</div>{showForm&&<AdminFormModal title={`${editing?'Edit':'Add'} advertisement`} subtitle="Configure the campaign once; the public site applies timing, audience and frequency automatically." onClose={closeForm}><div className="space-y-4"><Field label="Title"><input value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></Field><UploadField label="Desktop / main image" value={form.image} onChange={v=>setForm({...form,image:v})} folder="ads"/><UploadField label="Mobile image (optional)" value={form.mobileImage||''} onChange={v=>setForm({...form,mobileImage:v})} folder="ads"/><Field label="Click link"><input value={form.link} onChange={e=>setForm({...form,link:e.target.value})} placeholder="https://..." inputMode="url"/></Field><Field label="Placement"><select value={form.placement||'banner'} onChange={e=>setForm({...form,placement:e.target.value as AdPlacement})}><option value="banner">Banner — homepage carousel</option><option value="popup">Popup — timed campaign</option><option value="inline">Inline — content area</option></select></Field><Field label="Audience"><select value={form.audience||'all'} onChange={e=>setForm({...form,audience:e.target.value as AdAudience})}><option value="all">Everyone</option><option value="free">Free users only</option><option value="vip">VIP users only</option></select></Field><div className="grid sm:grid-cols-2 gap-3"><Field label="Priority"><input type="number" value={form.priority??0} onChange={e=>setForm({...form,priority:Number(e.target.value)})}/></Field><Field label="Order"><input type="number" value={form.order??1} onChange={e=>setForm({...form,order:Number(e.target.value)})}/></Field><Field label="Start (optional)"><input type="datetime-local" value={form.startAt||''} onChange={e=>setForm({...form,startAt:e.target.value})}/></Field><Field label="End (optional)"><input type="datetime-local" value={form.endAt||''} onChange={e=>setForm({...form,endAt:e.target.value})}/></Field><Field label="Popup frequency (seconds)"><input type="number" min="0" value={form.frequencySeconds??20} onChange={e=>setForm({...form,frequencySeconds:Math.max(0,Number(e.target.value)||0)})}/></Field><Field label="Skip close after (seconds)"><input type="number" min="0" value={form.skipAfterSeconds??5} onChange={e=>setForm({...form,skipAfterSeconds:Math.max(0,Number(e.target.value)||0)})}/></Field></div><label className="flex items-center gap-3 text-sm font-bold"><input type="checkbox" checked={!!form.enabled} onChange={e=>setForm({...form,enabled:e.target.checked})}/><span>Active / visible</span></label><div className="flex gap-2"><button onClick={closeForm} className="admin-secondary-btn flex-1">Cancel</button><button onClick={async()=>{await save();setShowForm(false)}} className="admin-primary-btn flex-1">{editing?'Save changes':'Add advertisement'}</button></div></div></AdminFormModal>}</div>
}
function PlacementIcon({type}:{type:string}){return type==='popup'?<MousePointerClick size={12}/>:type==='inline'?<LayoutTemplate size={12}/>:<MonitorPlay size={12}/>}
